3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { planningTempFor, rainAheadFor } from "@/lib/weather/planning";
8	import { readPreferences } from "@/lib/profile/preferences";
9	import { personalBand, planningTemp } from "@/lib/generator/rules";
10	import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
11	import { rankTopN } from "@/lib/generator/rank";
12	import { currentSeason } from "@/lib/generator/season";
13	import { rerank } from "@/lib/generator/rerank";
14	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
15	import { localDateFor } from "@/lib/outfits/local-date";
16	import { assertCanGenerate, noteGeneration, QuotaExceededError } from "@/lib/outfits/quota";
17	import { predictOccasion } from "@/lib/outfits/predict-occasion";
18	import { pinItem, styledLookName, shortlistFor, STYLED_LOOKS } from "@/lib/outfits/styled";
19	import {
20	  loadStyledLooks,
21	  saveStyledLooks,
22	  clearStyledLooks,
23	  loadStyledPieceIds,
24	} from "@/lib/outfits/styled-store";
25	import { resolveLocation } from "@/lib/weather/location";
26	import type { LookDraft, LookPiece, WeatherPayload } from "@/lib/generator/types";
27	
28	export type StyleResult =
29	  | { status: "ok"; outfitIds: string[] }
30	  // Carries the seam's own reason. Styling is a Pro capability rather than a
31	  // daily allowance, so a message written here ("back tomorrow") would be
32	  // actively false — tomorrow gives a free user no stylings either.
33	  | { status: "limited"; message: string }
34	  | { status: "empty"; message: string }
35	  | { status: "error"; message: string };
36	
37	/**
38	 * "Style an outfit with this" (Fitcheck.dc.html:654).
39	 *
40	 * Pins the piece, runs the deterministic pipeline, spends ONE text call to name
41	 * and explain the result, then persists it keyed by (user, item, local day) so a
42	 * second tap the same day is a free read.
43	 *
44	 * This does not contradict Decision 5. That decision says never pay twice for a
45	 * question already answered — which is why the daily drop caches. "What goes
46	 * with this piece?" is a different question from "what should I wear today?",
47	 * so it gets its own answer, cached the same way.
48	 *
49	 * The alternative readings were measured and rejected; see the plan
50	 * `todo/2026-07-24-item-detail-rebuild.md`.
51	 */
52	export async function styleWithItem(
53	  itemId: string,
54	  opts?: { regenerate?: boolean },
55	): Promise<StyleResult> {
56	  try {
57	    const supabase = await createClient();
58	    const {
59	      data: { user },
60	    } = await supabase.auth.getUser();
61	    if (!user) return { status: "error", message: "Not signed in" };
62	
63	    const { data: profile } = await supabase
64	      .from("profiles")
65	      .select(
66	        "archetype, formality_min, formality_max, occasions, location_lat, location_lon, location_label, location_source, location_timezone, preferences",
67	      )
68	      .eq("id", user.id)
69	      .single();
70	
71	    const { data: itemsRaw } = await supabase
72	      .from("items")
73	      .select("*")
74	      .eq("user_id", user.id)
75	      .eq("archived", false);
76	    const items = itemsRaw ?? [];
77	    const subject = items.find((i) => i.id === itemId);
78	    if (!subject) return { status: "error", message: "Piece not found" };
79	
80	    // Fragrance occupies no slot in a look, so there is nothing to build around.
81	    if (subject.category === "Fragrance") {
82	      return { status: "empty", message: "Fragrance finishes a look rather than forming one." };
83	    }
84	
85	    const now = new Date();
86	    // The date key comes from the PROFILE timezone, not the forecast's, so the
87	    // cache can be checked without a network call — the same zone `toggleWear`
88	    // and `predictDefaultOccasion` use.
89	    const today = localDateFor(now, profile?.location_timezone ?? "UTC");
90	
91	    // THE CACHE. Checked before the quota is touched and before any I/O beyond
92	    // this one indexed lookup — re-opening an answer you already have must never
93	    // cost anything.
94	    // A regenerate deliberately skips the cache — that is the whole point of
95	    // the control. Everything else is a free read, per Decision 5.
96	    const cached = opts?.regenerate ? [] : await loadStyledLooks(user.id, itemId, today);
97	    if (cached.length) return { status: "ok", outfitIds: cached };
98	
99	    // Checked before the forecast fetch below: a free user is turned away
100	    // without us paying for I/O they will never see. The occasion is not needed
101	    // here — a styled look is a flat capability (Pro #2), not a counted meter —
102	    // and it is resolved a few lines down, in time for the ledger.
103	    try {
104	      await assertCanGenerate(user.id, { kind: "styled", today });
105	    } catch (e) {
106	      if (e instanceof QuotaExceededError) return { status: "limited", message: e.message };
107	      throw e;
108	    }
109	
110	    const loc = resolveLocation({ profile });
111	    const f = await fetchForecast(loc.lat, loc.lon);
112	    const prefs = readPreferences(profile?.preferences);
113	    const advice = laterAdvice(f.hourly, prefs.tempUnit, f.highC);
114	    const weather: WeatherPayload = {
115	      tempC: f.tempC,
116	      feelsLikeC: f.feelsLikeC,
117	      condition: f.condition,
118	      cityLabel: loc.label,
119	      timezone: f.timezone,
120	      locationOrigin: loc.origin,
121	      laterSentence: advice.sentence,
122	      adviceClause: advice.adviceClause,
123	      laterLabel: "Later",
124	      hourly: f.hourly,
125	      tempUnit: prefs.tempUnit,
126	    };
127	
128	    // The occasion the app already believes you are dressing for today — the CTA
129	    // has no picker, and a look styled for the wrong context is worse than one
130	    // that simply agrees with the rest of the day.
131	    const occasion = predictOccasion(now, f.timezone, profile?.occasions ?? []);
132	
133	    /**
134	     * Pinning, done BEFORE candidate building rather than after.
135	     *
136	     * Dropping every rival in the subject's own category means any combo using
137	     * that category uses THIS piece. Filtering the built list instead would have
138	     * to survive the 200-combo CAP, and a piece that never made the cut would
139	     * silently produce "no looks" — the same class of bug as the coverage
140	     * defect fixed in PR #14.
141	     */
142	    const pool = items.filter((i) => i.category !== subject.category || i.id === itemId);
143	    const candItems: CandidateItem[] = pool.map((i) => ({
144	      id: i.id,
145	      colors: i.colors ?? [],
146	      category: i.category,
147	      formality: i.formality,
148	      seasons: i.seasons ?? [],
149	      material: i.material,
150	      texture: i.texture,
151	      pattern: i.pattern,
152	    }));
153	
154	    const args = {
155	      weather: {
156	        tempC: f.tempC,
157	        // Rain while the look is WORN, on the same clock as the temperature.
158	        rain: rainAheadFor(occasion, f.restOfDay),
159	        // The look is built for the day, not for this minute.
160	        // Same rule on the styled path: the look is built for the window the
161	        // chosen occasion is worn in, not for whenever the user tapped.
