202	      band,
203	      weather: {
204	        tempC: f.tempC,
205	        // Rain while the look is WORN, on the same clock as the temperature.
206	        rain: rainAheadFor(input.occasion, f.restOfDay),
207	        // The look is built for the day, not for this minute.
208	        // The peak of the window this occasion is actually WORN in. An Evening
209	        // look chosen at 14:00 must not be built for the afternoon.
210	        highC: planningTempFor(input.occasion, f.restOfDay, f.tempC),
211	        lowC: f.lowC,
212	      },
213	      season: currentSeason(now),
214	      excludeItemIds: [],
215	      maxAccessories: 1,
216	      rainGuard: prefs.rainGuard,
217	    };
218	    const combos = buildCandidates(candItems, candidateArgs);
219	    if (combos.length === 0) {
220	      return { status: "empty", weather, missing: missingCategory(candItems, candidateArgs) };
221	    }
