236	    const ranked = rankTopN(
237	      combos,
238	      {
239	        aesthetic,
240	        band,
241	        lean: input.lean,
242	        recentlyShown,
243	        season: candidateArgs.season,
244	        // The day's high, not the current reading — the drop is generated once
245	        // and worn all day. `planningTemp` is the single definition of that.
246	        tempC: planningTemp(candidateArgs.weather),
247	      },
248	      combos.length,
249	    );
250	    const top = diversify(ranked, 20);
251	
252	    // A look the user has already worn today is PINNED: saveDailyLooks leaves it
253	    // in place, so it has to survive in what we hand back to the screen too —
254	    // otherwise the day's set silently loses it until the next page load. It
255	    // also still COUNTS toward the day's three, so the stylist is asked for
256	    // fewer fresh looks rather than the set growing a fourth tab.
257	    const pinnedStored = (stored ?? []).filter((s) => s.worn);
