285	        ...top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!))),
286	        ...pinnedStored.flatMap((s) =>
287	          s.pieces.map((p) => pathFor(p.itemId)).filter((p): p is string => Boolean(p)),
