292	
293	    // `rerank` already dropped picks that repeat a combo or point outside the
294	    // shortlist, so every index here resolves. It previously fell back to
295	    // `top[0]` for an unknown index, which turned a bad index into a duplicate
296	    // of the first look rather than into one fewer look.
297	    const drafts: LookDraft[] = picks.map((p) => {
